"use client";

import type React from "react";

import { useState } from "react";
import { login } from "@/lib/api/auth";
import { useAuth } from "@/context/AuthContext";
import { useRouter } from "next/navigation";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const { refreshUser } = useAuth();
  const router = useRouter();

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    setIsLoading(true);

    const res = await login(email, password);

    if (!res.success) {
      setError(res.error || "Login failed");
      setIsLoading(false);
      return;
    }

    await refreshUser();
    router.push("/");
  }

  return (
    <div className="min-h-screen bg-[#0b0f19] flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-[#1e293b] border border-slate-700/60 rounded-2xl p-8 shadow-2xl shadow-slate-950/80 space-y-6">
          {/* Brand Text Name */}
          <div className="flex flex-col items-center space-y-3">
            <div className="flex items-center justify-center py-2.5 px-6 rounded-xl bg-slate-900 border border-slate-700 shadow-md">
              <span className="text-3xl font-black tracking-widest text-white">
                DMS
              </span>
            </div>
            <div className="text-center space-y-1 pt-1">
              <h1 className="text-base sm:text-lg font-bold tracking-widest text-white">
                DRONE MANAGEMENT SYSTEM
              </h1>
              <p className="text-xs text-slate-400 font-medium">Command Center Secure Access</p>
            </div>
          </div>

          {/* Login Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Error Message */}
            {error && (
              <div className="p-3 rounded-lg bg-red-500/10 border border-red-500/30">
                <p className="text-xs text-red-400 font-medium">{error}</p>
              </div>
            )}

            {/* Email Input */}
            <div className="space-y-2">
              <label
                htmlFor="email"
                className="block text-xs font-semibold uppercase tracking-wider text-slate-300"
              >
                Email Address
              </label>
              <input
                id="email"
                type="email"
                placeholder="operator@dms.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="w-full px-4 py-2.5 rounded-lg border border-slate-700 bg-[#0b0f19] text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all text-sm"
              />
            </div>

            {/* Password Input */}
            <div className="space-y-2">
              <label
                htmlFor="password"
                className="block text-xs font-semibold uppercase tracking-wider text-slate-300"
              >
                Password
              </label>
              <input
                id="password"
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-full px-4 py-2.5 rounded-lg border border-slate-700 bg-[#0b0f19] text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all text-sm"
              />
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading}
              className="w-full mt-2 px-4 py-3 rounded-lg bg-blue-600 hover:bg-blue-500 text-white font-semibold shadow-lg shadow-blue-600/20 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed hover:cursor-pointer flex items-center justify-center gap-2"
            >
              {isLoading ? "Signing in..." : "Sign in to Command Center"}
            </button>
          </form>

          {/* Footer */}
          <p className="text-center text-xs text-slate-500 pt-2">
            © 2026 Drone Management System (DMS). All rights reserved.
          </p>
        </div>
      </div>
    </div>
  );
}
